// PostgreSQL schema for GetInRoute (production path).
// Mirrors the FINAL SQLite shape produced by db.js (all base tables plus every
// additive ALTER). Everything is unquoted/lowercase, ids are BIGINT identity
// (GENERATED BY DEFAULT AS IDENTITY so the migration tool can insert preserved
// ids and the app can still auto-generate), timestamps stay TEXT in the exact
// SQLite format 'YYYY-MM-DD HH:MM:SS' local time.
//
// Helper functions:
//   app_tz()  -> timezone name from GUC app.time_zone (default Asia/Kolkata)
//   log_now() -> 'YYYY-MM-DD HH:MM:SS'    (replaces datetime('now','localtime'))
//   log_today()-> 'YYYY-MM-DD'            (replaces date('now','localtime'))
// The pgdb adapter replays the SQLite date/time dialect on top of these.

module.exports = {
  PG_SCHEMA: `
CREATE OR REPLACE FUNCTION app_tz() RETURNS text AS $$
  SELECT COALESCE(NULLIF(current_setting('app.time_zone', true), ''), 'Asia/Kolkata');
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION log_now() RETURNS text AS $$
  SELECT to_char(now() AT TIME ZONE app_tz(), 'YYYY-MM-DD HH24:MI:SS');
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION log_today() RETURNS text AS $$
  SELECT to_char(now() AT TIME ZONE app_tz(), 'YYYY-MM-DD');
$$ LANGUAGE sql;

CREATE TABLE IF NOT EXISTS users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  role TEXT NOT NULL CHECK (role IN ('admin','employee','driver','vendor','student','parent')),
  emp_id TEXT UNIQUE,
  email TEXT UNIQUE,
  name TEXT NOT NULL,
  phone TEXT,
  department TEXT,
  designation TEXT,
  password_hash TEXT NOT NULL,
  approved INTEGER DEFAULT 1,
  status TEXT DEFAULT 'active',
  lat DOUBLE PRECISION,
  lng DOUBLE PRECISION,
  last_update TEXT,
  vehicle_id BIGINT,
  reset_token TEXT,
  reset_expiry TEXT,
  created_at TEXT DEFAULT log_now(),
  locked_until TEXT,
  last_login TEXT,
  login_count INTEGER DEFAULT 0,
  home_address TEXT,
  home_lat DOUBLE PRECISION,
  home_lng DOUBLE PRECISION,
  pending_address TEXT,
  pending_lat DOUBLE PRECISION,
  pending_lng DOUBLE PRECISION,
  vendor_id BIGINT,
  invite_code TEXT,
  vertical TEXT NOT NULL DEFAULT 'company',
  school_id BIGINT,
  company_id BIGINT,
  location_profile TEXT,
  gender TEXT,
  driver_verified INTEGER DEFAULT 0,
  safety_drop_eligible INTEGER DEFAULT 0,
  must_change_password INTEGER DEFAULT 0,
  pickup_radius DOUBLE PRECISION,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS routes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  name TEXT NOT NULL,
  start_point TEXT,
  end_point TEXT,
  speed_limit DOUBLE PRECISION DEFAULT 40,
  stops TEXT NOT NULL,
  status TEXT DEFAULT 'active',
  created_at TEXT DEFAULT log_now(),
  vertical TEXT NOT NULL DEFAULT 'company',
  school_id BIGINT,
  sequence_control TEXT NOT NULL DEFAULT 'admin',
  start_lat DOUBLE PRECISION,
  start_lng DOUBLE PRECISION,
  end_lat DOUBLE PRECISION,
  end_lng DOUBLE PRECISION,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS vehicles (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  vehicle_name TEXT NOT NULL,
  plate TEXT,
  type TEXT,
  driver_name TEXT,
  driver_phone TEXT,
  line INTEGER DEFAULT 1,
  trip INTEGER DEFAULT 1,
  route_id BIGINT,
  capacity INTEGER DEFAULT 4,
  stand TEXT,
  vendor_id BIGINT,
  speed DOUBLE PRECISION DEFAULT 0,
  lat DOUBLE PRECISION,
  lng DOUBLE PRECISION,
  last_update TEXT,
  status TEXT DEFAULT 'idle',
  created_at TEXT DEFAULT log_now(),
  live_status TEXT DEFAULT 'idle',
  current_stop INTEGER DEFAULT 0,
  vertical TEXT NOT NULL DEFAULT 'company',
  school_id BIGINT,
  speed_limit DOUBLE PRECISION,
  connected INTEGER DEFAULT 0,
  gps_status TEXT DEFAULT 'stopped',
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS schedules (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  employee_id BIGINT NOT NULL,
  vehicle_id BIGINT,
  route_id BIGINT,
  date TEXT,
  pickup_time TEXT,
  drop_time TEXT,
  login_time TEXT,
  logout_time TEXT,
  sequence INTEGER,
  status TEXT DEFAULT 'scheduled',
  approved INTEGER DEFAULT 1,
  created_at TEXT DEFAULT log_now(),
  state TEXT DEFAULT 'pending',
  cancelled_by BIGINT,
  cancelled_at TEXT,
  safety_status TEXT,
  vertical TEXT NOT NULL DEFAULT 'company',
  school_id BIGINT,
  absent INTEGER DEFAULT 0,
  boarded_at TEXT,
  dropped_at TEXT,
  drop_confirmed INTEGER DEFAULT 0,
  drop_confirmed_by BIGINT,
  drop_otp TEXT,
  direction TEXT,
  checkin_otp TEXT,
  cancel_status TEXT,
  cancel_reason TEXT,
  source TEXT DEFAULT 'admin',
  pickup_point TEXT,
  drop_mode TEXT DEFAULT 'door',
  missed_email_sent INTEGER DEFAULT 0,
  missed_email_type TEXT,
  archived_at TEXT,
  archived_by BIGINT,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS checkins (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  schedule_id BIGINT,
  user_id BIGINT,
  type TEXT CHECK (type IN ('checkin','checkout')),
  lat DOUBLE PRECISION,
  lng DOUBLE PRECISION,
  time TEXT DEFAULT log_now(),
  method TEXT DEFAULT 'swipe',
  schedule_date TEXT,
  otp TEXT,
  confirmed INTEGER DEFAULT 0,
  otp_expires TEXT,
  otp_attempts INTEGER DEFAULT 0,
  archived_at TEXT,
  archived_by BIGINT,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS feedback (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  user_id BIGINT,
  role TEXT,
  schedule_id BIGINT,
  rating INTEGER,
  message TEXT,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS notifications (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  user_id BIGINT,
  title TEXT,
  message TEXT,
  read INTEGER DEFAULT 0,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS speed_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  vehicle_id BIGINT,
  vehicle_name TEXT,
  driver_name TEXT,
  speed DOUBLE PRECISION,
  speed_limit DOUBLE PRECISION,
  lat DOUBLE PRECISION,
  lng DOUBLE PRECISION,
  created_at TEXT DEFAULT log_now(),
  archived_at TEXT,
  archived_by BIGINT,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS parking_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  vehicle_id BIGINT,
  vehicle_name TEXT,
  plate TEXT,
  driver_id BIGINT,
  driver_name TEXT,
  parking_line TEXT,
  trip_date TEXT,
  vertical TEXT DEFAULT 'company',
  school_id BIGINT,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS driver_cancel_requests (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  vehicle_id BIGINT,
  driver_id BIGINT,
  all_stop_ids TEXT,
  reason TEXT,
  status TEXT DEFAULT 'pending',
  resolved_at TEXT,
  vertical TEXT DEFAULT 'company',
  school_id BIGINT,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS chat_messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  sender_id BIGINT,
  receiver_id BIGINT,
  message TEXT,
  read INTEGER DEFAULT 0,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS trip_chat_messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  trip_id TEXT NOT NULL,
  sender_id BIGINT,
  sender_role TEXT,
  message TEXT,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS route_employees (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  route_id BIGINT NOT NULL,
  employee_id BIGINT NOT NULL,
  created_at TEXT DEFAULT log_now(),
  UNIQUE (route_id, employee_id),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS sms_log (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  to_phone TEXT,
  message TEXT,
  provider TEXT,
  status TEXT,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS vendors (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  name TEXT NOT NULL,
  email TEXT UNIQUE,
  phone TEXT,
  password_hash TEXT,
  status TEXT DEFAULT 'active',
  assigned_locations TEXT DEFAULT '[]',
  created_at TEXT DEFAULT log_now(),
  last_login TEXT,
  login_count INTEGER DEFAULT 0,
  vertical TEXT NOT NULL DEFAULT 'company',
  school_id BIGINT,
  vendor_code TEXT,
  assigned_route_ids TEXT DEFAULT '[]',
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS address_updates (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  user_id BIGINT NOT NULL,
  old_address TEXT,
  new_address TEXT,
  new_lat DOUBLE PRECISION,
  new_lng DOUBLE PRECISION,
  status TEXT DEFAULT 'pending',
  reviewed_by BIGINT,
  reviewed_at TEXT,
  created_at TEXT DEFAULT log_now(),
  vertical TEXT NOT NULL DEFAULT 'company',
  school_id BIGINT,
  pickup_radius DOUBLE PRECISION,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS settings (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  data TEXT NOT NULL DEFAULT '{}'
);

CREATE TABLE IF NOT EXISTS nodal_points (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  label TEXT NOT NULL,
  address TEXT,
  lat DOUBLE PRECISION,
  lng DOUBLE PRECISION,
  type TEXT DEFAULT 'office',
  radius_meters INTEGER DEFAULT 1000,
  created_at TEXT DEFAULT log_now(),
  vertical TEXT NOT NULL DEFAULT 'company',
  school_id BIGINT,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS tickets (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  created_by BIGINT NOT NULL,
  assigned_to BIGINT,
  escalation_level TEXT DEFAULT 'employee' CHECK (escalation_level IN ('employee','admin','owner')),
  status TEXT DEFAULT 'open' CHECK (status IN ('open','in_progress','escalated','resolved','closed')),
  priority TEXT DEFAULT 'medium' CHECK (priority IN ('low','medium','high','urgent')),
  category TEXT DEFAULT 'general',
  subject TEXT NOT NULL,
  description TEXT,
  created_at TEXT DEFAULT log_now(),
  updated_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS ticket_comments (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  ticket_id BIGINT NOT NULL,
  user_id BIGINT NOT NULL,
  message TEXT NOT NULL,
  is_internal INTEGER DEFAULT 0,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS ticket_history (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  ticket_id BIGINT NOT NULL,
  user_id BIGINT,
  user_name TEXT,
  action TEXT NOT NULL,
  old_value TEXT,
  new_value TEXT,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS schools (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  name TEXT NOT NULL,
  contact_phone TEXT,
  support_email TEXT,
  status TEXT DEFAULT 'active',
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS school_settings (
  school_id BIGINT PRIMARY KEY,
  data TEXT NOT NULL DEFAULT '{}'
);

CREATE TABLE IF NOT EXISTS student_profiles (
  user_id BIGINT PRIMARY KEY,
  class_grade TEXT,
  section TEXT,
  education_level TEXT DEFAULT 'school' CHECK (education_level IN ('school','college')),
  can_login INTEGER DEFAULT 0,
  guardian_name_1 TEXT,
  guardian_phone_1 TEXT,
  guardian_name_2 TEXT,
  guardian_phone_2 TEXT,
  emergency_name TEXT,
  emergency_phone TEXT,
  notes TEXT
);

CREATE TABLE IF NOT EXISTS parent_children (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  parent_id BIGINT NOT NULL,
  student_id BIGINT NOT NULL,
  relation TEXT,
  created_at TEXT DEFAULT log_now(),
  UNIQUE (parent_id, student_id),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS sos_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  school_id BIGINT,
  reporter_id BIGINT,
  reporter_role TEXT,
  student_id BIGINT,
  vehicle_id BIGINT,
  lat DOUBLE PRECISION,
  lng DOUBLE PRECISION,
  message TEXT,
  status TEXT DEFAULT 'open',
  created_at TEXT DEFAULT log_now(),
  resolved_at TEXT,
  resolved_by BIGINT,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS geofence_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  school_id BIGINT,
  zone_id BIGINT,
  vehicle_id BIGINT,
  student_id BIGINT,
  event TEXT CHECK (event IN ('enter','exit')),
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS realtime_usage (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  month TEXT NOT NULL UNIQUE,
  messages INTEGER DEFAULT 0,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS driver_heartbeats (
  user_id BIGINT PRIMARY KEY,
  connected INTEGER DEFAULT 0,
  last_ping TEXT,
  reconnecting INTEGER DEFAULT 0,
  reconnecting_since TEXT,
  disconnected_at TEXT,
  created_at TEXT DEFAULT log_now(),
  updated_at TEXT DEFAULT log_now()
);

CREATE TABLE IF NOT EXISTS location_history (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  subject TEXT NOT NULL CHECK (subject IN ('vehicle','user')),
  subject_id BIGINT NOT NULL,
  lat DOUBLE PRECISION NOT NULL,
  lng DOUBLE PRECISION NOT NULL,
  speed DOUBLE PRECISION DEFAULT 0,
  source TEXT DEFAULT 'gps',
  created_at TEXT DEFAULT log_now(),
  archived_at TEXT,
  archived_by BIGINT,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS import_audit_log (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  user_id BIGINT,
  user_name TEXT,
  entity TEXT NOT NULL,
  source TEXT NOT NULL,
  filename TEXT,
  total_rows INTEGER DEFAULT 0,
  valid_rows INTEGER DEFAULT 0,
  duplicate_rows INTEGER DEFAULT 0,
  error_rows INTEGER DEFAULT 0,
  inserted_rows INTEGER DEFAULT 0,
  skipped_rows INTEGER DEFAULT 0,
  rejected_json TEXT,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS safety_alerts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  schedule_id BIGINT,
  employee_id BIGINT,
  employee_name TEXT,
  driver_id BIGINT,
  driver_name TEXT,
  vehicle_id BIGINT,
  vehicle_name TEXT,
  trip_id TEXT,
  lat DOUBLE PRECISION,
  lng DOUBLE PRECISION,
  vertical TEXT NOT NULL DEFAULT 'company',
  school_id BIGINT,
  status TEXT NOT NULL DEFAULT 'pending',
  kind TEXT NOT NULL DEFAULT 'safety',
  note TEXT,
  created_at TEXT DEFAULT log_now(),
  updated_at TEXT,
  resolved_at TEXT,
  resolved_by BIGINT,
  resolved_by_role TEXT,
  action TEXT,
  archived_at TEXT,
  archived_by BIGINT,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS trip_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  schedule_id BIGINT,
  employee_id BIGINT,
  employee_name TEXT,
  vehicle_id BIGINT,
  date TEXT,
  kind TEXT NOT NULL,
  meta TEXT,
  created_at TEXT DEFAULT log_now(),
  archived_at TEXT,
  archived_by BIGINT,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS eddie_projects (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  user_id BIGINT NOT NULL,
  name TEXT NOT NULL,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS eddie_subscriptions (
  user_id BIGINT PRIMARY KEY,
  plan_id TEXT DEFAULT 'free',
  created_at TEXT DEFAULT log_now(),
  updated_at TEXT DEFAULT log_now()
);

CREATE TABLE IF NOT EXISTS eddie_usage (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  user_id BIGINT NOT NULL,
  date TEXT NOT NULL,
  count INTEGER DEFAULT 1,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_eddie_usage ON eddie_usage(user_id, date);

CREATE TABLE IF NOT EXISTS geo_route_cache (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  cache_key TEXT UNIQUE NOT NULL,
  profile TEXT NOT NULL DEFAULT 'driving',
  points TEXT NOT NULL,
  result TEXT NOT NULL,
  distance_meters DOUBLE PRECISION,
  duration_seconds DOUBLE PRECISION,
  expires_at BIGINT NOT NULL,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_geo_route_cache_key ON geo_route_cache(cache_key);

CREATE TABLE IF NOT EXISTS geo_result_cache (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  kind TEXT NOT NULL CHECK (kind IN ('search','reverse')),
  cache_key TEXT UNIQUE NOT NULL,
  result TEXT NOT NULL,
  expires_at BIGINT NOT NULL,
  created_at TEXT DEFAULT log_now(),
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_geo_result_cache_key ON geo_result_cache(kind, cache_key);

CREATE INDEX IF NOT EXISTS idx_schedules_emp ON schedules(employee_id);
CREATE INDEX IF NOT EXISTS idx_schedules_vehicle ON schedules(vehicle_id);
CREATE INDEX IF NOT EXISTS idx_checkins_sched ON checkins(schedule_id);
CREATE INDEX IF NOT EXISTS idx_veh_line_trip ON vehicles(line, trip);
CREATE INDEX IF NOT EXISTS idx_chat_sender ON chat_messages(sender_id, receiver_id);
CREATE INDEX IF NOT EXISTS idx_chat_receiver ON chat_messages(receiver_id, sender_id);
CREATE INDEX IF NOT EXISTS idx_trip_chat_trip ON trip_chat_messages(trip_id, id);
CREATE INDEX IF NOT EXISTS idx_route_emps_route ON route_employees(route_id);
CREATE INDEX IF NOT EXISTS idx_tickets_created ON tickets(created_by);
CREATE INDEX IF NOT EXISTS idx_tickets_status ON tickets(status);
CREATE INDEX IF NOT EXISTS idx_ticket_comments_ticket ON ticket_comments(ticket_id);
CREATE INDEX IF NOT EXISTS idx_ticket_history_ticket ON ticket_history(ticket_id);
CREATE INDEX IF NOT EXISTS idx_parent_children_student ON parent_children(student_id);
CREATE INDEX IF NOT EXISTS idx_parent_children_parent ON parent_children(parent_id);
CREATE INDEX IF NOT EXISTS idx_sos_student ON sos_events(student_id, status);
CREATE INDEX IF NOT EXISTS idx_geofence_vehicle ON geofence_events(vehicle_id, created_at);
CREATE INDEX IF NOT EXISTS idx_location_history_subject ON location_history(subject, subject_id, id);
CREATE INDEX IF NOT EXISTS idx_safety_alerts_status ON safety_alerts(status, created_at);
CREATE INDEX IF NOT EXISTS idx_safety_alerts_schedule ON safety_alerts(schedule_id);
CREATE INDEX IF NOT EXISTS idx_trip_events_schedule ON trip_events(schedule_id, created_at);
CREATE INDEX IF NOT EXISTS idx_trip_events_kind ON trip_events(kind, created_at);
`
};